// Original wallpapers generated by scripts/gen-wallpapers.mjs (see /public/wallpapers).
// Locally supplied pictures in src/custom-assets/ are appended (see core/customAssets.ts).
import { CUSTOM_WALLPAPERS, CUSTOM_LOCK_WALLPAPERS } from './customAssets';
import { assetUrl } from './assets';
export interface WallpaperDef {
  id: string;
  name: string;
  url: string;
  thumb: string;
  /** Theme the wallpaper is designed for */
  tone: 'light' | 'dark';
  /** Average colour, used for Mica tint fallbacks and "automatic" accent */
  avg: string;
}

const base = import.meta.env.BASE_URL;
const w = (id: string, name: string, tone: 'light' | 'dark', avg: string): WallpaperDef => ({
  id, name, tone, avg,
  url: assetUrl(`${base}wallpapers/${id}.jpg`),
  thumb: assetUrl(`${base}wallpapers/${id}-thumb.jpg`),
});

export const WALLPAPERS: WallpaperDef[] = [
  w('flow-light', 'Flow (light)', 'light', '#9fc3ec'),
  w('flow-dark', 'Flow (dark)', 'dark', '#0f2a5c'),
  w('glow', 'Glow', 'dark', '#2a2366'),
  w('aurora', 'Aurora', 'dark', '#0e3b3a'),
  w('dune', 'Dune', 'light', '#d9a77a'),
  w('lagoon', 'Lagoon', 'light', '#4cb3c4'),
  w('ember', 'Ember', 'dark', '#5a1f2e'),
  w('mist', 'Mist', 'light', '#c9ced8'),
];

// User-provided wallpapers go first so the first one can become the default.
WALLPAPERS.unshift(...CUSTOM_WALLPAPERS.map((c) => ({ id: c.id, name: c.name, url: c.url, thumb: c.url, tone: 'light' as const, avg: '#7f9fc4' })));

export const LOCK_WALLPAPERS: WallpaperDef[] = [
  w('lock-ridge', 'Ridge', 'dark', '#33506e'),
  w('lock-coast', 'Coast', 'light', '#6aa1c8'),
];
LOCK_WALLPAPERS.unshift(...CUSTOM_LOCK_WALLPAPERS.map((c) => ({ id: c.id, name: c.name, url: c.url, thumb: c.url, tone: 'dark' as const, avg: '#33506e' })));

/** Default desktop / lock pictures (a locally supplied picture wins). */
export const DEFAULT_WALLPAPER_ID = CUSTOM_WALLPAPERS[0]?.id ?? 'flow-light';
export const DEFAULT_LOCK_WALLPAPER_ID = CUSTOM_LOCK_WALLPAPERS[0]?.id ?? 'lock-ridge';

export function wallpaperById(id: string): WallpaperDef | undefined {
  return [...WALLPAPERS, ...LOCK_WALLPAPERS].find((x) => x.id === id);
}
